        => new HtmlString(string.Create(System.Globalization.CultureInfo.InvariantCulture,
            $"<svg class=\"{cssClass}\" viewBox=\"0 0 20 20\" fill=\"currentColor\" aria-hidden=\"true\" focusable=\"false\">{Paths[name]}</svg>"));
